INSERT INTO yoga_poses (title, category, difficulty, description, benefits, safety_notes, steps, image_url, video_url, display_order, is_active) VALUES
('Mountain Pose (Tadasana)', 'Standing', 'Beginner', 'A grounding standing posture that encourages upright alignment and steady breathing.', 'Posture awareness, balance, mindful breathing.', 'Stand near a wall if balance is difficult. Stop if you feel dizzy or uncomfortable.', 'Stand tall with feet grounded and weight evenly distributed.\nLengthen your spine and relax your shoulders.\nLet arms rest by your sides and breathe slowly for 5–8 breaths.', 'assets/images/yoga/mountain.svg', 'https://www.youtube.com/results?search_query=Mountain+Pose+Tadasana+beginner+yoga', 1, TRUE),
('Child’s Pose (Balasana)', 'Restorative', 'Beginner', 'A gentle resting pose that can be used between movements.', 'Relaxation and gentle back/hip mobility.', 'Do not force the hips down. Use a cushion under the hips or forehead if needed.', 'Kneel on a comfortable mat and bring big toes together.\nEase hips toward heels and fold forward only as far as comfortable.\nRest arms forward or beside the body and breathe gently.', 'assets/images/yoga/child.svg', 'https://www.youtube.com/results?search_query=Child+Pose+Balasana+beginner+yoga', 2, TRUE),
('Cat-Cow', 'Mobility', 'Beginner', 'A slow spinal movement coordinated with comfortable breathing.', 'Gentle spinal mobility and body awareness.', 'Move within a pain-free range and pad the knees. Avoid straining the neck.', 'Come onto hands and knees with wrists below shoulders.\nExhale and gently round the back without forcing the neck.\nInhale and lengthen the spine, moving slowly between positions.', 'assets/images/yoga/cat-cow.svg', 'https://www.youtube.com/results?search_query=Cat+Cow+pose+beginner+yoga', 3, TRUE),
('Cobra Pose (Bhujangasana)', 'Backbend', 'Beginner', 'A gentle chest-opening movement with a low lift.', 'Upper-body awareness and gentle extension.', 'Keep the lift small. Stop if you feel lower-back, wrist, or shoulder pain.', 'Lie on your stomach with palms near the ribs.\nKeep elbows close and gently lift the chest using back muscles.\nKeep the pelvis grounded and lower slowly.', 'assets/images/yoga/cobra.svg', 'https://www.youtube.com/results?search_query=Low+Cobra+Pose+Bhujangasana+beginner+yoga', 4, TRUE),
('Tree Pose (Vrksasana)', 'Balance', 'Beginner', 'A standing balance posture with a supported variation.', 'Balance and concentration.', 'Use a wall for support. Place the foot on the calf or thigh, never directly against the knee.', 'Stand tall and focus on a steady point.\nPlace one foot on the inner calf or thigh, avoiding the knee.\nBring hands together if comfortable and switch sides.', 'assets/images/yoga/tree.svg', 'https://www.youtube.com/results?search_query=Tree+Pose+Vrksasana+beginner+yoga', 5, TRUE),
('Savasana', 'Restorative', 'Beginner', 'A relaxed resting posture to settle the body after movement.', 'Relaxation and calm breathing.', 'Use a pillow under the knees if your lower back feels strained. Get up slowly.', 'Lie on your back with legs comfortably apart.\nLet arms rest by your sides with palms facing up.\nRelax the face and breathe naturally for 2–5 minutes.', 'assets/images/yoga/savasana.svg', 'https://www.youtube.com/results?search_query=Savasana+guided+relaxation+yoga', 6, TRUE),
('Gentle Breathing', 'Breathwork', 'Beginner', 'Easy, unforced breathing while seated comfortably.', 'Breath awareness and relaxation.', 'Do not hold your breath or force deep breathing. Stop if you feel dizzy or short of breath.', 'Sit comfortably with your spine supported.\nBreathe in gently through the nose without straining.\nExhale slowly and naturally, keeping the breath comfortable.', 'assets/images/yoga/breathing.svg', 'https://www.youtube.com/results?search_query=gentle+diaphragmatic+breathing+beginner', 7, TRUE)
INSERT INTO symptoms (title, category, description, self_care_guidance, warning_signs, disclaimer) VALUES
('Headache', 'Common concerns', 'Headaches can have many causes including stress, dehydration, eye strain, or illness.', 'Rest in a quiet space, drink water, and consider whether sleep or screen breaks may help. Ask a pharmacist or clinician before using medicine.', 'Seek urgent care for a sudden severe headache, weakness, confusion, fainting, fever with stiff neck, or headache after a serious injury.', 'This information is educational and cannot identify the cause of a headache.'),
('Fatigue', 'Common concerns', 'Feeling unusually tired can be associated with sleep, stress, nutrition, or underlying conditions.', 'Maintain a regular sleep schedule, eat balanced meals, hydrate, and pace activities. Seek medical advice if it persists.', 'Seek urgent help for fatigue with chest pain, severe breathlessness, confusion, or fainting.', 'Persistent or unexplained fatigue needs professional assessment.'),
('Fever', 'Common concerns', 'Fever is a rise in body temperature that can occur with infections and other conditions.', 'Rest, drink fluids, monitor temperature, and follow professional advice for medicines.', 'Seek urgent care for breathing difficulty, confusion, seizure, stiff neck, severe dehydration, or fever in a very young infant.', 'This guide does not replace an examination by a clinician.'),
('Sore Throat', 'Common concerns', 'A sore throat may be caused by a viral illness, irritation, allergies, or other conditions.', 'Drink fluids, rest your voice, and consider warm drinks if comfortable. Avoid smoke and other irritants.', 'Get urgent help if breathing or swallowing becomes difficult, or if there is swelling of the neck or throat.', 'A clinician can assess persistent, severe, or recurrent symptoms.'),
('Mild Indigestion', 'Digestive health', 'Indigestion can cause discomfort or fullness after eating and has several possible causes.', 'Try smaller meals, eat slowly, and note any foods that appear to trigger symptoms.', 'Seek urgent care for severe chest or abdominal pain, vomiting blood, black stools, or difficulty breathing.', 'Do not assume chest discomfort is indigestion; seek urgent care when concerned.'),
('Seasonal Allergy Symptoms', 'Allergy', 'Sneezing, itchy eyes, or a runny nose may occur with seasonal allergens.', 'Reduce exposure where practical and rinse your face after outdoor activities. Ask a pharmacist or clinician about suitable options.', 'Seek emergency help for swelling of the lips or tongue, difficulty breathing, or collapse.', 'This guide does not confirm an allergy diagnosis.')
