USE healthhub;

ON DUPLICATE KEY UPDATE description=VALUES(description), benefits=VALUES(benefits), safety_notes=VALUES(safety_notes), steps=VALUES(steps), image_url=VALUES(image_url), video_url=VALUES(video_url), is_active=TRUE;

ON DUPLICATE KEY UPDATE description=VALUES(description), self_care_guidance=VALUES(self_care_guidance), warning_signs=VALUES(warning_signs), disclaimer=VALUES(disclaimer);
